#!/usr/bin/env bash
# OWNER: HOM-31
# EXTENDED: S4-W (compiles Classes/Tools/PdfNewFiles.swift, the shared exclusive-create output helper.)
#
# XCTests of the Flutter-free compress core (Classes/Compress/PdfCompressCore.swift over
# Classes/Viewer/PdfCore.swift) without the Danaview app, assembled in a temporary Swift package
# from the pod sources; fixtures are generated by the tests (no downloads):
#
#   macos            `swift test` on this Mac.
#   ios <simulator>  `xcodebuild test` of the same package on an iOS Simulator, by name or UDID
#                    (it must exist; boot it first, the script never boots or shuts one down).
#
# The `HOM31|…` lines the tests print are the measured sizes (BUILD_STATE, HOM-31). The Pigeon
# glue of compress is covered by Tests/Viewer/run_xctests.sh (Tests/Compress/Glue/). The temporary
# directory is removed on exit. Usage:
#   packages/danaview_pdf/darwin/Tests/Compress/run_compress_xctests.sh macos | ios "iPhone 17 Pro"
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
darwin="$(cd "$here/../.." && pwd)"
mode="${1:-macos}"

work="$(mktemp -d "${TMPDIR:-/tmp}/dv_pdf_compress_xctests.XXXXXX")"
cleanup() { rm -rf "$work"; }
trap cleanup EXIT

mkdir -p "$work/Sources/DanaviewPdfCompress" "$work/Tests/DanaviewPdfCompressTests"
for f in "$darwin/Classes/Viewer/PdfCore.swift" "$darwin/Classes/Tools/PdfNewFiles.swift" "$darwin/Classes/Compress/PdfCompressCore.swift"; do
  ln -s "$f" "$work/Sources/DanaviewPdfCompress/$(basename "$f")"
done
ln -s "$here/CompressFixtures.swift" "$work/Tests/DanaviewPdfCompressTests/CompressFixtures.swift"
{ echo "@testable import DanaviewPdfCompress"; cat "$here/PdfCompressCoreTests.swift"; } > "$work/Tests/DanaviewPdfCompressTests/PdfCompressCoreTests.swift"
cat > "$work/Package.swift" <<'PKG'
// swift-tools-version:5.7
import PackageDescription
let package = Package(
  name: "DanaviewPdfCompress",
  platforms: [.macOS(.v11), .iOS(.v15)],
  products: [.library(name: "DanaviewPdfCompress", targets: ["DanaviewPdfCompress"])],
  targets: [
    .target(name: "DanaviewPdfCompress"),
    .testTarget(name: "DanaviewPdfCompressTests", dependencies: ["DanaviewPdfCompress"]),
  ]
)
PKG

case "$mode" in
  macos)
    (cd "$work" && swift test 2>&1) > "$work/test.log" || true
    ;;
  ios)
    sim="${2:?simulator name or UDID}"
    if [[ "$sim" =~ ^[0-9A-F-]{36}$ ]]; then dest="platform=iOS Simulator,id=$sim"; else dest="platform=iOS Simulator,name=$sim"; fi
    (cd "$work" && xcodebuild test -scheme DanaviewPdfCompress -destination "$dest" -derivedDataPath "$work/dd" 2>&1) > "$work/test.log" || true
    ;;
  *)
    echo "unknown mode $mode (macos | ios <simulator>)" >&2
    exit 2
    ;;
esac
grep -E "HOM31\||Test Case.*(passed|failed|skipped)|error:|Executed|\*\* TEST" "$work/test.log" || tail -40 "$work/test.log"
if grep -qE "with 0 failures|\*\* TEST SUCCEEDED \*\*" "$work/test.log" && ! grep -qE "error:|\*\* TEST FAILED \*\*" "$work/test.log"; then exit 0; fi
tail -60 "$work/test.log"
exit 1
